    turn_energy_cost = turn_cost * energy_left_frac ** 2  # Penalize sharp turns more heavily if energy is low
    fitness_cost = 1.0 - fits  # Forced battery swaps are costly
    return 1.0 / (dist_m + turn_cost + depot_proximity_cost + battery_fit_cost + energy_cost + turn_energy_cost + fitness_cost)
